/*
 * Supplementary index-arithmetic check for CVE-2022-32981 port.
 *
 * This is NOT a kernel build. It reproduces only the PPC32 layout of
 * struct thread_fp_state (u64 fpr[32][1]; u64 fpscr) and compares the
 * byte offsets produced by the pre-fix TS_FPR(fpidx) indexing with the
 * post-fix ((u32 *)fpr)[fpidx] indexing for fpidx = 0..64.
 *
 * Expected: old indexing goes past the 256-byte fpr array for fpidx >= 32
 * (overread/overwrite); new indexing stays within the struct.
 */
#include <stddef.h>
#include <stdio.h>

struct thread_fp_state {
	unsigned long long fpr[32][1] __attribute__((aligned(16)));
	unsigned long long fpscr;
};

#define TS_FPR(fs, i) ((unsigned char *)&(fs).fpr[i][0])

int main(void)
{
	const size_t fpr_bytes = sizeof(((struct thread_fp_state *)0)->fpr);
	const size_t fpscr_off = offsetof(struct thread_fp_state, fpscr);
	const size_t struct_bytes = sizeof(struct thread_fp_state);
	int old_oob = 0, new_oob = 0;

	printf("fpr_bytes=%zu fpscr_off=%zu struct_bytes=%zu sizeof(long)=%zu\n",
	       fpr_bytes, fpscr_off, struct_bytes, sizeof(unsigned long));

	for (unsigned int fpidx = 0; fpidx <= (PT_FPSCR_PLACEHOLDER); fpidx++) {
		struct thread_fp_state fs;
		size_t old_off = fpidx * sizeof(unsigned long long); /* TS_FPR(fs,fpidx) */
		size_t new_off = fpidx * sizeof(unsigned int);        /* ((u32*)fpr)[fpidx] */
		int old_bad = (old_off + sizeof(unsigned long) > fpr_bytes);
		int new_bad = (new_off + sizeof(unsigned int) > struct_bytes);
		if (old_bad)
			old_oob++;
		if (new_bad)
			new_oob++;
		if (fpidx == 31 || fpidx == 32 || fpidx == 63 || fpidx == 64)
			printf("fpidx=%2u old_off=%3zu old_bad=%d new_off=%3zu new_bad=%d\n",
			       fpidx, old_off, old_bad, new_off, new_bad);
	}

	printf("old_oob_count=%d new_oob_count=%d\n", old_oob, new_oob);
	if (old_oob == 0 || new_oob != 0)
		return 1;
	return 0;
}

